<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {download,date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StatusBadge from '../components/common/StatusBadge.vue';import StaleBadge from '../components/StaleBadge.vue';const research=useResearch(),auth=useAuth(),{error,busy,perform}=useTask(),runId=ref(0),sampleId=ref(0),message=ref('');const completed=computed(()=>research.runs.filter(r=>r.status==='completed')),current=computed(()=>research.current?.status==='completed'&&research.current.id===runId.value?research.current:null);const basisStale=computed(()=>research.staleById.get(runId.value)?.stale);const basisRecalc=computed(()=>research.recalcByRoot.get(runId.value));watch(runId,id=>{if(id)perform(()=>research.select(id))});watch(current,()=>{sampleId.value=current.value?.result.samples[0]?.id||0});onMounted(()=>perform(async()=>{await Promise.all([research.loadRuns(),research.loadNotes(),research.loadStale()]);runId.value=completed.value.find(r=>r.id===research.selected)?.id||completed.value[0]?.id||0;if(runId.value)await research.select(runId.value)}));async function submit(e:Event){const f=e.target as HTMLFormElement,d=new FormData(f);await research.addNote({name:d.get('name'),run_id:runId.value,sample_id:sampleId.value,protocol:d.get('protocol')});message.value='试样验证计划已提交，等待负责人审阅。';(f.elements.namedItem('name') as HTMLInputElement).value='';(f.elements.namedItem('protocol') as HTMLTextAreaElement).value=''}async function review(e:Event,id:number){const d=new FormData(e.target as HTMLFormElement);await research.review(id,String(d.get('status')),String(d.get('reviewer_note')));message.value='审阅决定已留档。'}
</script><template><PageHeading no="05" title="试样审阅" sub="把权衡中仍需验证的问题写成计划，由负责人审议试验安排。"/><ErrorNotice :error="error"/><p v-if="message" role="status" class="success">{{message}}</p><div class="note-spread"><section><h2 class="ruled-title">提出一份试样验证计划</h2><div v-if="!completed.length" class="empty"><p>完成一项权衡研究后，选择冻结候选试样并写下验证问题。</p><RouterLink to="/runs">先提交研究 →</RouterLink></div><form v-else @submit.prevent="e=>perform(()=>submit(e))"><label>依据研究<select aria-label="提案依据研究" v-model.number="runId"><option v-for="r in completed" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}{{r.recalc_of_id?`（重算v${r.recalc_seq}）`:''}}</option></select></label><div v-if="basisStale" class="stale-note"><StaleBadge :run-id="runId" small/><p class="muted">该依据的源数据已修订；计划仍将冻结在当前快照指纹上，旧计划不受影响。如需新依据，请选择重算后的版本。</p></div><label>计划名称<input name="name" minLength="2" maxLength="140" required placeholder="例如：LY01湿热前后吸声复测"/></label><label>冻结候选试样<select name="sample_id" aria-label="验证试样" v-model.number="sampleId" required><option v-for="s in current?.result.samples||[]" :key="s.id" :value="s.id">{{s.code}} {{s.name}}</option></select></label><label>验证问题与执行方案<textarea name="protocol" rows="6" minLength="10" maxLength="1800" required placeholder="说明材料权衡中的取舍、要检验的性能、试样条件及独立评价口径；不要把名次写成采购决定。"/></label><button class="primary" :disabled="busy||!auth.canEdit">提交负责人审阅 →</button><p v-if="!auth.canEdit" class="muted">观察员可阅读与分发已同意计划。</p></form><aside class="margin-note"><b>批准的是试样研究</b><p>不会自动采购、改写权重或追加测量。验证结果应另行录入资料库并建立新的权衡快照。</p><p>已留档的审批不能覆盖。需要修改时，新建修订计划。源数据重算不会改写已批准计划的原依据。</p></aside></section><section><h2 class="ruled-title">负责人审阅簿 <small>{{research.notes.length}}份</small></h2><div v-if="!research.notes.length" class="empty">还没有计划。先从结果中找出需要用试样验证的取舍。</div><article class="note-entry" v-for="n in research.notes" :key="n.id"><div class="entry-line"><small>TRIAL NOTE {{String(n.id).padStart(3,'0')}}</small><StatusBadge :status="n.status"/></div><h3>{{n.name}}</h3><p class="protocol">{{n.protocol}}</p><small>依据研究 #{{n.run_id}} / 冻结候选ID {{n.sample_id}} · {{date(n.created_at)}}</small><StaleBadge :run-id="n.run_id" small/><div v-if="n.reviewer_note" class="reviewer-note"><b>负责人批注</b><p>{{n.reviewer_note}}</p><small>{{n.reviewed_by}}</small></div><form v-if="auth.user?.role==='admin'&&n.status==='draft'" @submit.prevent="e=>perform(()=>review(e,n.id))"><label>审阅批注<textarea name="reviewer_note" minLength="5" maxLength="1000" required/></label><div class="button-row"><select name="status" aria-label="审阅决定"><option value="approved">同意试样验证</option><option value="rejected">退回修改</option></select><button :disabled="busy">留档决定</button></div></form><button v-if="n.status==='approved'" class="text-link" @click="perform(()=>download(n.id))">下载试样计划与权衡摘要 CSV ↙</button><p v-if="n.status==='approved'&&research.staleById.get(n.run_id)?.stale" class="muted">该计划批准时的快照依据保持有效，可继续分发；重算新版本仅作对照，不会改写本计划。</p></article></section></div></template>